//! Translation-layer tests for the exported symbols of spec §28 (12 entries).
//! Test names keep the exported C name verbatim (`sym_<name>`) for traceability.
#![allow(non_snake_case, clippy::as_conversions, clippy::arithmetic_side_effects, clippy::unwrap_used)]

use std::sync::Once;

use liella_boundary::posix::s28_profiling as pr;
use spectest::symbol;

// Two instrumented "functions" as gcc emits them (csys/src/machine/mcount.S fixtures): -pg
// -mfentry calls __fentry__ before the prologue; -pg calls mcount after `push rbp; mov rbp, rsp`.
// The glibc names exist only in the products, so the fixtures call the hidden liella_machine_*
// entry points behind them, from a known caller.

/// One monstartup per process (it is one-shot), over a text range around both sites and the caller.
fn start() -> [usize; 3] {
    static ONCE: Once = Once::new();
    let sites = pr::probe_sites();
    ONCE.call_once(|| {
        let low = sites.iter().min().unwrap() - (1 << 20);
        let high = sites.iter().max().unwrap() + (1 << 20);
        pr::monstartup(low, high);
    });
    sites
}

/// The arcs into `site` (its first 16 bytes) from `caller` (its first 4 KiB): (count of arcs, total).
fn arcs_into(site: usize, caller: usize) -> (u32, u32) {
    let (mut arcs, mut total) = (0, 0);
    pr::each_arc(|from, to, count| {
        if (site..site + 16).contains(&to) && (caller..caller + 4096).contains(&from) {
            arcs += 1;
            total += count;
        }
    });
    (arcs, total)
}

#[test]
fn sym___fentry__() {
    let [site, _, caller] = start();
    pr::probe_run(false, 5);
    let (arcs, total) = arcs_into(site, caller);
    assert!(arcs == 1 && total >= 5, "fentry arc not recorded: {arcs} arcs, {total} calls");
}

#[test]
fn sym_mcount() {
    let [_, site, caller] = start();
    pr::probe_run(true, 7);
    let (arcs, total) = arcs_into(site, caller);
    assert!(arcs == 1 && total >= 7, "mcount arc not recorded: {arcs} arcs, {total} calls");
}

#[test]
fn sym__mcount() {
    // _mcount is the same entry as mcount (one label, csys/src/machine/mcount.S).
    sym_mcount();
}

